'use strict';
const routeState={hash:'',positions:new Map(),sheetFrames:new Map(),sheetId:0,restoring:false};
let currentSheet=null,toastTimer=0,lastFocus=null;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800);}
function animateContent(el){if(!el||reduced())return;el.getAnimations().forEach(a=>a.cancel());el.animate([{opacity:.65,transform:'translateY(5px)'},{opacity:1,transform:'none'}],{duration:180,easing:'cubic-bezier(.2,0,0,1)'});}
function currentHash(){return state.view==='day'?'day-'+state.day:state.view==='map'?(mapFilter==='all'?'map':'map-'+mapFilter):state.view;}
function parseRoute(){const h=location.hash.slice(1),day=h.match(/^day-(\d+)$/),mp=h.match(/^map(?:-(\d+))?$/);if(day){state.day=Math.min(18,Math.max(1,+day[1]));state.view='day';}else if(mp){mapFilter=mp[1]&&+mp[1]>=1&&+mp[1]<=18?mp[1]:'all';state.view='map';}else state.view=['today','itinerary','toolbox'].includes(h)?h:({overview:'itinerary',orders:'toolbox',memo:'toolbox'})[h]||'home';if(state.view==='today')state.day=tripToday(new Date(),DATA.days,tripCalendarChanges).day;}
function saveScroll(){routeState.positions.set(routeState.hash,scrollY);history.replaceState({...history.state,y:scrollY},'',location.href);}
function navigate(view,day,options={}){if(currentSheet){hideDrawer();history.replaceState({route:routeState.hash,y:scrollY},'',location.href);}saveScroll();const previous={view:state.view,day:state.day,hash:routeState.hash,y:scrollY};if(day!==undefined)state.day=Math.min(18,Math.max(1,+day));if(view==='today')state.day=tripToday(new Date(),DATA.days,tripCalendarChanges).day;state.view=view;if(view==='map'&&previous.view!=='map')mapSource=previous;const hash=currentHash();if(!options.replace&&location.hash!=='#'+hash)history.pushState({route:hash,y:0},'','#'+hash);else history.replaceState({route:hash,y:0},'','#'+hash);render({scroll:options.scroll!==false});}
function render({scroll=true,restoreY=null}={}){const oldView=document.body.dataset.view;if(state.view!=='map')disposeMap();if(state.view==='today')state.day=tripToday(new Date(),DATA.days,tripCalendarChanges).day;const views={home,day:()=>dayView(false),today:()=>dayView(true),itinerary:itineraryView,map:mapPage,toolbox:toolboxView};$('#page').innerHTML=(views[state.view]||home)();document.body.dataset.view=state.view;routeState.hash=currentHash();document.title=journalTitle;renderRail();renderNav();updateClocks();if(state.view==='map')initMap();if(scroll)window.scrollTo({top:restoreY??0,behavior:'instant'});if(oldView!==state.view||scroll)$('#page').focus({preventScroll:true});setupSegments();persist();animateContent($('#page'));}
function renderNav(){const nav=$('#bottomNav');if(!nav.childElementCount){nav.innerHTML=[['today','今日','sun'],['itinerary','全部行程','calendar'],['map','地图','map'],['toolbox','工具箱','bag']].map(([v,n,i])=>`<button data-view="${v}">${outlineIco(i)}<span>${n}</span></button>`).join('');}nav.querySelectorAll('button').forEach(b=>{const active=b.dataset.view===state.view||(state.view==='day'&&b.dataset.view==='itinerary');b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false');});const todayButton=$('.top-actions [data-trip-today]');if(!todayButton){const b=document.createElement('button');b.className='text-button trip-today';b.dataset.tripToday='';b.textContent='今日';$('.top-actions').prepend(b);}$('#saveHtml').textContent='离线';$('#saveHtml').setAttribute('aria-label','离线资料与缓存');}
function renderRail(){const rail=$('#dayRail');if(['day','today'].includes(state.view)){rail.innerHTML='<p class="editor-label">OCT — NOV · 18 DAYS</p>'+DATA.days.map(d=>`<button data-day="${d.id}" class="calendar-tab ${d.id===state.day?'active':''}" ${d.id===state.day?'aria-current="date"':''}><strong>${shortDate(d.date)}</strong><small>${esc(d.title)}</small></button>`).join('');}else rail.innerHTML='<div class="desktop-links"><button data-view="home">杂志首页 ↗</button><button data-view="today">今日路书 ↗</button><button data-view="itinerary">全部行程 ↗</button><button data-view="map">路线地图 ↗</button><button data-view="toolbox">工具箱 ↗</button></div>';}
function showDrawerFrame(frame){currentSheet=frame;$('#drawerBody').innerHTML=`<h1 id="drawerTitle">${esc(frame.title)}</h1>${frame.body}`;$('.drawer').scrollTop=frame.scroll||0;$('#closeDrawer').textContent=frame.parent?'← 返回上一级':'关闭 ×';$('#overlay').inert=false;$('#overlay').setAttribute('aria-hidden','false');$('#overlay').classList.add('open');['mainShell','bottomNav','topbar'].forEach(id=>$('#'+id).inert=true);document.body.style.overflow='hidden';updateClocks();const im=$('.detail-photo img');if(im){im.tabIndex=0;im.setAttribute('role','button');im.setAttribute('aria-label','全屏查看'+im.alt);}requestAnimationFrame(()=>{if(currentSheet===frame)$('#closeDrawer').focus({preventScroll:true});});animateContent($('#drawerBody'));}
function openDrawer(title,body){if(currentSheet)currentSheet.scroll=$('.drawer').scrollTop;const frame={id:++routeState.sheetId,title,body,parent:currentSheet,focus:document.activeElement,scroll:0};routeState.sheetFrames.set(frame.id,frame);if(!currentSheet){lastFocus=document.activeElement;saveScroll();}history.pushState({...history.state,sheet:frame.id},'',location.href);showDrawerFrame(frame);}
function hideDrawer(){if(!currentSheet)return;const focus=currentSheet.focus;currentSheet=null;$('#overlay').classList.remove('open');$('#overlay').setAttribute('aria-hidden','true');$('#overlay').inert=true;['mainShell','bottomNav','topbar'].forEach(id=>$('#'+id).inert=false);document.body.style.overflow='';if(focus?.isConnected)focus.focus({preventScroll:true});else lastFocus?.focus({preventScroll:true});}
function closeDrawer(){if(!currentSheet)return;if(history.state?.sheet){history.back();}else hideDrawer();}
function openDates(mapMode=false){openDrawer(mapMode?'选择地图日期':'选择行程日期',`<p class="info-caption">按真实旅程顺序分组，选择后立即打开。</p><div class="date-sheet">${mapMode?'<button class="date-option" data-mapday="all">北欧全程</button>':''}${mapMode?dateRows().replace(/data-day=/g,'data-mapday='):dateRows()}</div>`);requestAnimationFrame(()=>$('.date-sheet .selected')?.scrollIntoView({block:'center',behavior:'instant'}));}
function changePlan(){const d=DATA.days[state.day-1],pos=scrollY,transport=$('.transport-grid');$('#planTimeline').innerHTML=renderTimeline(d);$('#planNow').innerHTML=timeCard(d);$('#dayExtras').innerHTML=extraDay(d);if($('#transportOptions'))$('#transportOptions').innerHTML=d.id===1&&state.variants[1]==='B'?transportBox():'';if(transport&&$('.transport-grid')){$('.transport-grid').replaceWith(transport);transport.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.transport===state.transport)));}document.querySelectorAll('[data-variant]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.variant===state.variants[state.day])));setupSegments();persist();animateContent($('#planTimeline'));window.scrollTo({top:pos,behavior:'instant'});}
function openBooking(day){const b=DATA.bookings.find(b=>b.day===+day);if(!b)return;openDrawer(b.name,`<p class="detail-en">${dateText(DATA.days[b.day-1].date)} · ${b.people}位</p><p><strong>${esc(b.time)}</strong></p><p>路书报到目标：${esc(b.report)}</p><p>${esc(b.note)}</p><p>集合位置：${esc(b.place)}</p>${bookingNavigation(b)}<button class="small-link" data-day="${b.day}">打开当天安排 →</button>`);}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-copy]');if(!b||b.disabled)return;const a=b.dataset;
 if(a.day){if(+a.day<1||+a.day>18)return;navigate('day',+a.day);}
 else if(a.view){if(a.view==='map'&&state.view==='map'){mapFilter='all';updateMap();return;}mapFilter=a.view==='map'?'all':mapFilter;navigate(a.view);}
 else if(b.hasAttribute('data-trip-today'))navigate('today');
 else if(b.hasAttribute('data-dates'))openDates();
 else if(b.hasAttribute('data-map-dates'))openDates(true);
 else if(a.mapday){if(currentSheet){hideDrawer();history.replaceState({route:routeState.hash,y:scrollY},'',location.href);}const same=state.view==='map';mapFilter=a.mapday;if(same){history.pushState({route:currentHash(),y:scrollY},'','#'+currentHash());routeState.hash=currentHash();updateMap();const control=$('[data-map-dates]');control.textContent=mapFilter==='all'?'选择单日 ⌄':dateText(DATA.days[+mapFilter-1].date)+' ⌄';$('[data-mapday="all"]').setAttribute('aria-pressed',String(mapFilter==='all'));}else navigate('map');}
 else if(a.countryFilter){browseCountry=a.countryFilter;document.querySelectorAll('[data-country-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.countryFilter===browseCountry)));$('#compactIndex').innerHTML=compactDays($('#destinationSearch').value);moveSlider($('.country-segments'));animateContent($('#compactIndex'));}
 else if(a.variant){state.variants[state.day]=a.variant;changePlan();}
 else if(a.transport){state.transport=a.transport;changePlan();}
 else if(a.mapPlace)selectMapPlace(a.mapPlace);
 else if(b.hasAttribute('data-fit'))fitMap();
 else if(b.hasAttribute('data-map-return')){const origin=mapSource;mapSource=null;if(origin){navigate(origin.view,origin.day,{scroll:false});window.scrollTo({top:origin.y,behavior:'instant'});}else navigate('itinerary');}
 else if(a.navigation)openDrawer('选择导航方式',navigationBody(a.navigation));
 else if(a.place||a.venue)openPlace(a.place||a.venue);
 else if(a.hotel)openHotel(a.hotel);
 else if(a.booking)openBooking(a.booking);
 else if(a.notes)openDrawer(DATA.days[+a.notes-1].title+' · 详细说明','<div class="rich">'+markdown(DATA.days[+a.notes-1].notes)+'</div>');
 else if(a.guide||a.detail)detail(a.guide||a.detail);
 else if(a.tool){const names={activities:'活动预订',flights:'航班',hotels:'全部住宿',transport:'交通与自驾',lists:'清单与采购',emergency:'天气与安全',offline:'离线与备忘'};openDrawer(names[a.tool],toolBody(a.tool));}
 else if(a.copy)copyLink(a.copy,'内容');
 else if(b.id==='closeDrawer')closeDrawer();
 else if(b.hasAttribute('data-share'))shareJournal();
 else if(b.hasAttribute('data-copy-link'))copyLink(location.href);
 else if(b.hasAttribute('data-offline')||b.id==='saveHtml')openDrawer('离线资料',offlineBody());
 else if(b.hasAttribute('data-cache-prepare'))prepareOffline();
 else if(b.hasAttribute('data-update'))applyOfflineUpdate();
 else if(b.hasAttribute('data-now')){const p=planPosition(DATA.days[state.day-1]);const target=p.current>=0?p.current:p.next;if(target>=0)$('#step-'+target)?.scrollIntoView({block:'center',behavior:reduced()?'instant':'smooth'});else toast('当前日期没有可定位的精确计划时段');}
 else if(a.stepFocus!==undefined)$('#step-'+a.stepFocus)?.scrollIntoView({block:'center',behavior:reduced()?'instant':'smooth'});
 else if(a.scrollId)$('#'+a.scrollId)?.scrollIntoView({block:'start',behavior:reduced()?'instant':'smooth'});
 else if(a.expand){const panel=$('#'+b.getAttribute('aria-controls')),open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));panel.inert=!open;panel.classList.toggle('open',open);}
 else if(a.photo)openPhoto(a.photo,b.querySelector('img'));
 else if(b.hasAttribute('data-photo-close'))closePhoto();
 else if(b.hasAttribute('data-photo-next'))showPhoto(photoIndex+1);
 else if(b.hasAttribute('data-photo-prev'))showPhoto(photoIndex-1);
 else if(b.hasAttribute('data-top'))window.scrollTo({top:0,behavior:reduced()?'instant':'smooth'});
 else if(b.hasAttribute('data-credits'))openDrawer('照片来源与许可',`<p>照片沿用原项目。分享图为Eric Kilby的CC BY-SA 2.0冰洞照片；其他原图转载许可由项目持有人复核。</p><a href="share/LICENSE.txt">分享封面许可</a>${Object.entries(CREDITS).map(([k,c])=>`<p>${esc(c.title||k)} · ${esc(c.author||'原项目来源')}<br>${c.source?ext(c.source,'原始来源',''):''}</p>`).join('')}`);
});
document.addEventListener('input',e=>{if(e.target.id==='destinationSearch')$('#compactIndex').innerHTML=compactDays(e.target.value);});
document.addEventListener('change',e=>{if(e.target.dataset.check){state.checks[e.target.dataset.check]=e.target.checked;persist();if(currentSheet)currentSheet.body=$('#drawerBody').innerHTML.replace(/^[\s\S]*?<\/h1>/,'');}});
document.addEventListener('click',e=>{const im=e.target.closest('.detail-photo img');if(!im)return;const key=Object.keys(DATA.places).find(k=>pImage(k)===im.getAttribute('src'));if(key)openPhoto(key,im);});
$('#overlay').addEventListener('click',e=>{if(e.target===$('#overlay'))closeDrawer();});
document.addEventListener('keydown',e=>{if(!viewer.hidden)return;if(e.key==='Enter'||e.key===' '){if(e.target.matches('.detail-photo img')){e.preventDefault();e.target.click();}}if(!currentSheet)return;if(e.key==='Escape'){e.preventDefault();closeDrawer();}if(e.key==='Tab'){const controls=[...$('.drawer').querySelectorAll('button,a[href],input,select,[tabindex="0"]')].filter(x=>!x.disabled&&x.getClientRects().length),first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('popstate',e=>{const frame=e.state?.sheet&&routeState.sheetFrames.get(e.state.sheet);if(frame){showDrawerFrame(frame);return;}hideDrawer();const wasMap=state.view==='map';parseRoute();if(wasMap&&state.view==='map'&&map){updateMap();routeState.hash=currentHash();const control=$('[data-map-dates]');control.textContent=mapFilter==='all'?'选择单日 ⌄':dateText(DATA.days[+mapFilter-1].date)+' ⌄';return;}render({restoreY:e.state?.y??routeState.positions.get(currentHash())??0});});
window.addEventListener('hashchange',()=>{if(location.hash.slice(1)===routeState.hash)return;hideDrawer();parseRoute();render();});
let lastPlanMinute='';function refreshTime(){const now=new Date();updateClocks(now);const stamp=now.toISOString().slice(0,16);if(stamp===lastPlanMinute)return;lastPlanMinute=stamp;if(state.view==='today'){const t=tripToday(now,DATA.days,tripCalendarChanges);if(t.day!==state.day){state.day=t.day;render({scroll:false});return;}}if(['day','today'].includes(state.view)){$('#planNow').innerHTML=timeCard(DATA.days[state.day-1],now);const pos=planPosition(DATA.days[state.day-1],now);document.querySelectorAll('#planTimeline .timeline-row').forEach((row,i)=>{row.classList.toggle('is-current',i===pos.current);row.classList.toggle('is-next',i===pos.next);const badge=row.querySelector('.step-state');if(badge)badge.textContent=i===pos.current?'当前计划':i===pos.next?'下一项':'';});}}
document.addEventListener('visibilitychange',()=>{if(!document.hidden){lastPlanMinute='';refreshTime();}});window.addEventListener('pageshow',()=>{lastPlanMinute='';refreshTime();});setInterval(refreshTime,30000);
window.addEventListener('resize',()=>{setupSegments();map?.invalidateSize();},{passive:true});matchMedia('(prefers-reduced-motion: reduce)').addEventListener?.('change',setupSegments);
history.scrollRestoration='manual';parseRoute();history.replaceState({route:currentHash(),y:0},'','#'+currentHash());render();

let offlineRegistration=null;
function offlineBody(){return `<p>缓存成功后可在同一浏览器、同一网址查询每日时间线、酒店地址、集合地点、航班、应急资料与清单。外部导航与官方状态查询仍需联网。</p><p id="offlineStatus" role="status">${navigator.serviceWorker?'浏览器缓存尚未核验，请保持联网并准备。':'此浏览器不支持自动缓存，请使用下面的精简资料页。'}</p><button class="primary-link" data-cache-prepare>准备并核验离线资料</button><div class="offline-links"><a href="essentials.html">打开精简资料页（可打印 / 保存） ↗</a><a href="offline.html" download="北境路书_2026_完整离线版.html">下载原完整离线版（约12MB） ↓</a><a href="compat.html">完整无脚本阅读版 ↗</a></div><p class="info-caption">微信可能限制下载或清除缓存。重要资料请在系统浏览器保存并断网试开；页面不会把点击下载视为已经保存成功。</p>`;}
async function prepareOffline(){const status=$('#offlineStatus');if(!navigator.serviceWorker){status.textContent='此浏览器不支持缓存，请保存精简资料页。';return;}status.textContent='正在准备并核验，请保持网络连接…';try{offlineRegistration=await navigator.serviceWorker.register('sw.js');await navigator.serviceWorker.ready;const worker=offlineRegistration.active;if(!worker)throw Error('缓存服务尚未启动');const result=await new Promise((resolve,reject)=>{const channel=new MessageChannel(),timer=setTimeout(()=>reject(Error('准备超时，请联网后重试')),90000);channel.port1.onmessage=e=>{clearTimeout(timer);e.data.ok?resolve(e.data):reject(Error(e.data.error||'部分资源保存失败'));};worker.postMessage({type:'PREPARE'},[channel.port2]);});status.textContent=`已核验${result.count}项关键资源。请断网重开同一网址验证；浏览器清理缓存后需重新准备。`;try{localStorage.setItem('nordic-offline-verified',new Date().toISOString());}catch{}}catch(e){status.textContent='未完成离线准备：'+e.message+'。可保存精简资料页。';}}
function applyOfflineUpdate(){if(offlineRegistration?.waiting)offlineRegistration.waiting.postMessage({type:'ACTIVATE'});else location.reload();}
if(navigator.serviceWorker&&location.protocol!=='file:')navigator.serviceWorker.register('sw.js').then(r=>{offlineRegistration=r;const offer=()=>{if(r.waiting&&navigator.serviceWorker.controller){const banner=document.createElement('aside');banner.className='update-banner';banner.innerHTML='路书有新版本 <button data-update>更新并重开</button>';document.body.append(banner);}};offer();r.addEventListener('updatefound',()=>r.installing?.addEventListener('statechange',offer));}).catch(()=>{});
let refreshing=false,wasControlled=!!navigator.serviceWorker?.controller;navigator.serviceWorker?.addEventListener('controllerchange',()=>{if(!wasControlled){wasControlled=true;return;}if(navigator.serviceWorker.controller&&!refreshing){refreshing=true;location.reload();}});
